int checks=0;void check(bool b){++checks;if(!b){std::cerr<<"failed "<<checks<<'\n';std::abort();}}
void near(double a,double b){check(std::abs(a-b)<1e-9);}
template<class F>void reject(F f,const char* expected){try{f();check(false);}catch(const std::exception& e){if(std::string(e.what())!=expected)std::cerr<<e.what()<<" expected "<<expected<<'\n';check(std::string(e.what())==expected);}}
void train(CreatureObject& c){c.skills.insert("outdoors_squadleader_novice");c.skills.insert("outdoors_squadleader_master");for(auto branch:{"offense","movement","support","defense"})for(int i=1;i<=4;++i)c.skills.insert("outdoors_squadleader_"+std::string(branch)+"_0"+std::to_string(i));for(auto id:{"steadyaim","rally","formup","boostmorale","retreat"})c.grants.insert(id);c.mods["group_melee_defense"]=c.mods["group_ranged_defense"]=30;}
Json request(const char* ability,const char* shot){return {{"ability_id",ability},{"shot_id",shot},{"item_id","9"},{"target_id","2"},{"origin",{0,1,0}},{"direction",{0,0,1}}};}
